code='def day_summary(hours,temperatures):\n    low=high=temperatures[0]\n    total=night_total=0\n    night_count=0\n    for i in range(len(hours)):\n        value=temperatures[i]\n        total+=value\n        if value<low:\n            low=value\n        if value>high:\n            high=value\n        if hours[i]>=20 or hours[i]<6:\n            night_total+=value\n            night_count+=1\n    return high,low,total/len(temperatures),night_total/night_count'
